--- a/src/factura.mjs
+++ b/src/factura.mjs
@@ -8,15 +8,20 @@ export function validarNit(nit) {
 }

 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: `descuentoGlobal` (entero 0-100, %) se aplica sobre el total de las líneas, redondeado al centavo;
+// el IVA y el neto se calculan sobre el total ya descontado.
+export function calcularFactura(items, { descuentoGlobal = 0 } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  if (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100)
+    throw new RangeError("Descuento global inválido: debe ser un porcentaje entero de 0 a 100");
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const totalCentavos = Math.round((subtotalCentavos * (100 - descuentoGlobal)) / 100);
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
 }
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..af35a61 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -22,6 +22,49 @@ test("ADR-001: montos en centavos enteros", () => {
   assert.throws(() => calcularFactura([]));
 });

+const LINEAS_RF006 = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("T-601 RF-006: descuento global de 10 % sobre el total de las líneas", () => {
+  assert.equal(calcularFactura(LINEAS_RF006, { descuentoGlobal: 10 }).totalCentavos, 9945);
+});
+
+test("T-602 RF-006/RF-002: IVA y neto se recalculan sobre el total descontado", () => {
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("T-603 RF-006: sin descuentoGlobal el resultado es el de siempre", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_RF006), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_RF006, {}), esperado);
+});
+
+test("T-604 RF-006/ADR-001: descuentoGlobal no entero -> RangeError", () => {
+  assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: 10.5 }), RangeError);
+  assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: "10" }), RangeError);
+});
+
+test("T-605 RF-006: descuentoGlobal fuera de 0-100 -> RangeError", () => {
+  assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: -1 }), RangeError);
+  assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: 101 }), RangeError);
+});
+
+test("T-606 RF-006: 0 % no cambia el total y 100 % lo deja en cero", () => {
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 0 }), { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 });
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 100 }), { totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0 });
+});
+
+test("T-607 RF-006: el redondeo al centavo usa Math.round", () => {
+  // 15 centavos con 10 % -> 13,5 centavos -> 14
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 15 }], { descuentoGlobal: 10 }).totalCentavos, 14);
+});
+
 test("RF-003: una factura emitida no se puede modificar", () => {
   const f = emitirFactura({ numero: 7, nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 1, precioUnitarioCentavos: 1000 }] });
   assert.equal(f.estado, "emitida");
